import{_ as e,o as i,c as t,ag as l}from"./chunks/framework.Dx86EdC1.js";const p=JSON.parse('{"title":"Artikel, Halaman & Galeri","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/konten.md","filePath":"panduan-pengguna/konten.md","lastUpdated":1791382762000}'),n={name:"panduan-pengguna/konten.md"};function r(o,a,d,s,u,m){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="artikel-halaman-galeri" tabindex="-1">Artikel, Halaman &amp; Galeri <a class="header-anchor" href="#artikel-halaman-galeri" aria-label="Permalink to &quot;Artikel, Halaman &amp; Galeri&quot;">​</a></h1><p>Modul CMS dikelola di menu <strong>CMS Portal</strong> pada dashboard admin. Semua konten tampil di portal publik sesuai tema aktif.</p><h2 id="artikel-berita-admin-articles" tabindex="-1">Artikel / Berita (<code>/admin/articles</code>) <a class="header-anchor" href="#artikel-berita-admin-articles" aria-label="Permalink to &quot;Artikel / Berita (`/admin/articles`)&quot;">​</a></h2><p>Kelola berita, pengumuman, dan artikel desa.</p><h3 id="field-utama" tabindex="-1">Field Utama <a class="header-anchor" href="#field-utama" aria-label="Permalink to &quot;Field Utama&quot;">​</a></h3><ul><li><strong>Judul, slug, konten</strong> (WYSIWYG).</li><li><strong>Kategori &amp; tag</strong> (<code>/admin/categories</code>).</li><li><strong>Status</strong>: draft / dipublikasikan.</li><li><strong>Sampul — mode ganda (Dual-Mode)</strong>: <ul><li>Unggah berkas: <code>cover_image_file</code> (jpeg/png/jpg/webp/svg, maks 3 MB), disimpan di <code>storage/app/public/articles/</code>, diakses via <code>/storage/...</code>.</li><li><strong>atau</strong> URL gambar eksternal: <code>cover_image</code> (maks 500 karakter).</li></ul></li></ul><h3 id="di-portal-publik" tabindex="-1">Di Portal Publik <a class="header-anchor" href="#di-portal-publik" aria-label="Permalink to &quot;Di Portal Publik&quot;">​</a></h3><ul><li>Daftar: <code>/berita</code> — arsip lengkap.</li><li>Detail: <code>/berita/{slug}</code>.</li><li>Pengumuman: <code>/pengumuman</code>.</li><li>Per kategori: <code>/kategori/{slug}</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Saat mengganti sampul dengan berkas baru, berkas lama <strong>otomatis dihapus</strong> dari disk. Begitu pula saat artikel dihapus.</p></div><h2 id="halaman-statis-admin-pages" tabindex="-1">Halaman Statis (<code>/admin/pages</code>) <a class="header-anchor" href="#halaman-statis-admin-pages" aria-label="Permalink to &quot;Halaman Statis (`/admin/pages`)&quot;">​</a></h2><p>Untuk profil desa, visi-misi, struktur organisasi, dll. Ditampilkan di <code>/halaman/{slug}</code>. Konten melewati <em>sanitized typography rendering</em> — aman dari HTML berbahaya.</p><h2 id="galeri-admin-galleries" tabindex="-1">Galeri (<code>/admin/galleries</code>) <a class="header-anchor" href="#galeri-admin-galleries" aria-label="Permalink to &quot;Galeri (`/admin/galleries`)&quot;">​</a></h2><ol><li>Buat album (judul, slug, deskripsi, sampul — dual-mode seperti artikel).</li><li>Buka album → <strong>Tambah Foto</strong> (<code>image_file</code> maks 5 MB atau <code>image_url</code>).</li><li>Tampil di <code>/galeri</code> dan <code>/galeri/{slug}</code>.</li></ol><p>Foto lama otomatis dibersihkan saat diganti/dihapus.</p><h2 id="menu-navigasi-admin-menus" tabindex="-1">Menu Navigasi (<code>/admin/menus</code>) <a class="header-anchor" href="#menu-navigasi-admin-menus" aria-label="Permalink to &quot;Menu Navigasi (`/admin/menus`)&quot;">​</a></h2><p>Kelola menu header portal: label, tautan (ke halaman statis atau rute), urutan, status aktif, serta <strong>submenu bertingkat</strong> (dropdown). Menu dibaca oleh helper <code>public_header_menus()</code> pada tema.</p><h2 id="pengumuman-vs-berita" tabindex="-1">Pengumuman vs Berita <a class="header-anchor" href="#pengumuman-vs-berita" aria-label="Permalink to &quot;Pengumuman vs Berita&quot;">​</a></h2><p>Pengumuman adalah artikel dengan penanda khusus sehingga tampil terpisah di <code>/pengumuman</code> — gunakan untuk info resmi (bencana, jadwal layanan, rapat).</p>',18)])])}const c=e(n,[["render",r]]);export{p as __pageData,c as default};
